constraints:
1 <= N <= 10^{3}
1 <= arr[i] <= 10^{4}

expected time complexity: O(N).
expected auxiliary space: O(N).

standard_solution_code:
class Node:

	def __init__(self, data=0):
		self.data = data
		self.left = None
		self.right = None

def post_order(pre, size) -> Node:
	i = [0]

	def create(top, bottom):
		if i[0] >= len(pre):
			return None
		node = Node(pre[i[0]])
		if node.data > top or node.data < bottom:
			return None
		i[0] += 1
		node.left = create(node.data, bottom)
		node.right = create(top, node.data)
		return node
	return create(float('inf'), -float('inf'))
